272	const POINTS = {data_json};
273	const PHASE_COLORS = {json.dumps(PHASE_COLORS)};
274	const TRAVEL_COLOR = "#e0455a";
275	
276	const canvas = document.getElementById('c');
277	const ctx = canvas.getContext('2d');
278	let W, H, DPR;
279	function resize() {{
280	  DPR = window.devicePixelRatio || 1;
281	  W = canvas.clientWidth; H = canvas.clientHeight;
282	  canvas.width = W * DPR; canvas.height = H * DPR;
283	}}
284	window.addEventListener('resize', resize);
285	resize();
286	
287	// centre du modele (pour tourner autour de son propre milieu)
288	let cx = 0, cy = 0, cz = 0;
289	for (const p of POINTS) {{ cx += p.x; cy += p.y; cz += p.z; }}
290	cx /= POINTS.length; cy /= POINTS.length; cz /= POINTS.length;
291	
292	let maxExtent = 1;
293	for (const p of POINTS) {{
294	  maxExtent = Math.max(maxExtent, Math.abs(p.x - cx), Math.abs(p.y - cy), Math.abs(p.z - cz));
295	}}
296	
297	let rotX = -0.55, rotY = 0.65;
298	let zoom = 1.0;
299	let panX = 0, panY = 0;
300	let showTravel = false;
301	
302	function project(p) {{
303	  let x = p.x - cx, y = p.y - cy, z = p.z - cz;
304	  // rotation Y (autour de l'axe vertical ecran)
305	  let cosY = Math.cos(rotY), sinY = Math.sin(rotY);
306	  let x1 = x * cosY - y * sinY;
307	  let y1 = x * sinY + y * cosY;
308	  // rotation X (bascule)
309	  let cosX = Math.cos(rotX), sinX = Math.sin(rotX);
310	  let y2 = y1 * cosX - z * sinX;
311	  let z2 = y1 * sinX + z * cosX;
312	  const scale = (Math.min(W, H) * 0.38 / maxExtent) * zoom;
313	  return {{
314	    sx: W / 2 + x1 * scale + panX,
315	    sy: H / 2 - z2 * scale + panY,
316	    depth: y2,
317	  }};
318	}}
319	
320	function draw() {{
321	  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
322	  const bg = getComputedStyle(document.body).getPropertyValue('background-color') || '#0d0f14';
323	  ctx.clearRect(0, 0, W, H);
324	
325	  // segments d'extrusion, groupes par run contigu de la meme phase pour
326	  // eviter de relier deux extrusions separees par un trajet a vide.
327	  ctx.lineWidth = 1.15;
328	  ctx.lineJoin = 'round';
329	  let prevProj = null, prevExtruding = null, prevPhase = null;
330	
331	  for (let i = 0; i < POINTS.length; i++) {{
332	    const p = POINTS[i];
333	    const proj = project(p);
334	    if (prevProj) {{
335	      const isTravel = !(p.e && prevExtruding);
336	      if (isTravel) {{
337	        if (showTravel) {{
338	          ctx.strokeStyle = TRAVEL_COLOR;
339	          ctx.globalAlpha = 0.55;
340	          ctx.setLineDash([2, 3]);
341	          ctx.beginPath();
342	          ctx.moveTo(prevProj.sx, prevProj.sy);
343	          ctx.lineTo(proj.sx, proj.sy);
344	          ctx.stroke();
345	          ctx.setLineDash([]);
346	          ctx.globalAlpha = 1;
347	        }}
348	      }} else {{
349	        ctx.strokeStyle = PHASE_COLORS[p.p] || '#8fa3bf';
350	        ctx.globalAlpha = 0.92;
351	        ctx.beginPath();
352	        ctx.moveTo(prevProj.sx, prevProj.sy);
353	        ctx.lineTo(proj.sx, proj.sy);
354	        ctx.stroke();
355	        ctx.globalAlpha = 1;
356	      }}
357	    }}
358	    prevProj = proj;
359	    prevExtruding = p.e;
360	    prevPhase = p.p;
361	  }}
362	}}
363	
364	// --- interactions : rotation (glisser), pan (maj+glisser), zoom (molette) ---
365	let dragging = false, shiftDrag = false, lastX = 0, lastY = 0;
366	canvas.addEventListener('pointerdown', (ev) => {{
367	  dragging = true;
368	  shiftDrag = ev.shiftKey;
369	  lastX = ev.clientX; lastY = ev.clientY;
370	  canvas.classList.add('dragging');
371	  canvas.setPointerCapture(ev.pointerId);
372	}});
373	canvas.addEventListener('pointermove', (ev) => {{
374	  if (!dragging) return;
375	  const dx = ev.clientX - lastX, dy = ev.clientY - lastY;
376	  lastX = ev.clientX; lastY = ev.clientY;
377	  if (shiftDrag) {{
378	    panX += dx; panY += dy;
379	  }} else {{
380	    rotY += dx * 0.006;
381	    rotX += dy * 0.006;
382	    rotX = Math.max(-1.5, Math.min(1.5, rotX));
383	  }}
384	  draw();
385	}});
386	window.addEventListener('pointerup', () => {{ dragging = false; canvas.classList.remove('dragging'); }});
387	canvas.addEventListener('wheel', (ev) => {{
388	  ev.preventDefault();
389	  zoom *= Math.pow(1.0015, -ev.deltaY);
390	  zoom = Math.max(0.15, Math.min(12, zoom));
391	  draw();
392	}}, {{ passive: false }});
393	
394	document.getElementById('travel-toggle').addEventListener('click', (ev) => {{
395	  showTravel = !showTravel;
396	  ev.target.setAttribute('aria-pressed', String(showTravel));
397	  ev.target.textContent = 'trajets a vide : ' + (showTravel ? 'affiches' : 'masques');
398	  draw();
399	}});
400	
401	draw();
402	</script>
403	"""
404	
405	
406	def main() -> None:
407	    src = sys.argv[1] if len(sys.argv) > 1 else os.path.join("out", "l_overhang.gcode")
408	    dst = sys.argv[2] if len(sys.argv) > 2 else os.path.join(
409	        "out", "l_overhang_preview.html")
410	
411	    points = parse_gcode(src)
412	    points = decimate(points, target=20000)
413	
414	    html = build_html(points, os.path.basename(src))
415	    out_dir = os.path.dirname(dst)
416	    if out_dir:
417	        os.makedirs(out_dir, exist_ok=True)
418	    with open(dst, "w", encoding="utf-8") as f:
419	        f.write(html)
420	
421	    print(f"lu     : {src}")
422	    print(f"ecrit  : {dst}")
423	    print(f"points : {len(points)} (apres decimation)")
424	
425	
426	if __name__ == "__main__":
427	    main()
