function pointXYZ(p, applyC) {
  // p = [r, c, z, b, e, phase]. Dans le repere MACHINE, la matiere deposee
  // tourne avec le plateau : sa position ECRAN depend donc du C COURANT,
  // pas du C auquel elle a ete deposee. C'est tout l'interet de cette vue.
  const a = (applyC - p[1]) * Math.PI / 180;
  const r = p[0];
  // position de depot dans le repere plateau, ramenee a l'angle courant
  const c0 = p[1] * Math.PI / 180;
  const x0 = r * Math.cos(c0), y0 = r * Math.sin(c0);
  const ca = Math.cos(-a), sa = Math.sin(-a);
  return [x0 * ca - y0 * sa, x0 * sa + y0 * ca, p[2]];
}

