let headF = 0;   // position fractionnaire : `speed` peut valoir 0.25
function tick() {
  if (playing) {
    headF += speed;
    if (headF >= PTS.length - 1) { headF = PTS.length - 1; playing = false; syncPlay(); }
    const next = Math.floor(headF);
    if (next !== head) { head = next; draw(); }
    else if (speed >= 1) draw();
  }
  raf = requestAnimationFrame(tick);
}

