1	"""Exporte le G-code Apex en page HTML ANIMEE (plateau + tete + depot).
2	
3	Contrairement a scripts/preview_gcode.py (trace statique, repere PIECE), cette
4	vue anime le repere MACHINE : le plateau TOURNE (C), la tete se deplace dans
5	son demi-plan (R, Z) et s'incline (B). C'est le seul cadrage qui rend visible
6	l'oscillation de C et de R -- dans le repere piece, la rotation du plateau est
7	invisible par construction, puisqu'on la soustrait.
8	
9	Le fichier de sortie est autonome (aucun CDN, aucune dependance).
10	
11	Usage : python scripts/export_machine_animation.py [gcode] [sortie.html]
12	"""
13	
14	from __future__ import annotations
15	
16	import json
17	import math
18	import os
19	import re
20	import sys
21	
22	LINE_RE = re.compile(
23	    r"^G00"
24	    r"(?: Y(?P<c>-?\d+\.\d+))?"
25	    r"(?: X(?P<r>-?\d+\.\d+))?"
26	    r"(?: Z(?P<z>-?\d+\.\d+))?"
27	    r"(?: B(?P<b>-?\d+\.\d+))?"
28	    r"(?: E(?P<e>-?\d+\.\d+))?"
29	)
30	
31	PHASES = [("couche 1", "base"), ("pilier", "pilier"),
32	          ("coude", "coude"), ("surplomb", "surplomb")]
33	
34	
35	def parse(path: str) -> list[dict]:
36	    pts: list[dict] = []
37	    r = c = z = b = 0.0
38	    e_prev = 0.0
39	    phase = "base"
40	    for line in open(path, "r", encoding="ascii"):
41	        line = line.strip()
42	        if line.startswith(";"):
43	            # Seules les lignes de SECTION ("; --- ... ---" et "; couche 1")
44	            # marquent une phase. L'en-tete du fichier contient les mots
45	            # "coude" et "surplomb" dans sa description : les lire comme des
46	            # marqueurs classait le premier deplacement en phase "coude".
47	            if line.startswith("; ---") or line.startswith("; couche"):
48	                for needle, label in PHASES:
49	                    if needle in line:
50	                        phase = label
51	            continue
52	        m = LINE_RE.match(line)
53	        if not m:
54	            continue
55	        if m.group("c") is not None:
56	            c = float(m.group("c"))
57	        if m.group("r") is not None:
58	            r = float(m.group("r"))
59	        if m.group("z") is not None:
60	            z = float(m.group("z"))
61	        if m.group("b") is not None:
62	            b = float(m.group("b"))
63	        ext = False
64	        if m.group("e") is not None:
65	            ev = float(m.group("e"))
66	            ext = ev > e_prev + 1e-9
67	            e_prev = ev
68	        pts.append({"r": r, "c": c, "z": z, "b": b, "e": ext, "p": phase})
69	    if not pts:
70	        raise SystemExit(f"aucun point G00 dans {path}")
71	    return pts
72	
73	
74	def decimate(pts: list[dict], target: int) -> list[dict]:
75	    """Garde ~target points, SANS jamais fusionner deux points qui changent
76	    de phase ou d'etat d'extrusion : sinon un trajet a vide se retrouverait
77	    dessine comme un cordon depose (faux positif visuel)."""
78	    if len(pts) <= target:
79	        return pts
80	    stride = max(1, len(pts) // target)
81	    out = []
82	    prev = None
83	    for i, p in enumerate(pts):
84	        keep = (i % stride == 0 or i == len(pts) - 1 or prev is None
85	                or p["p"] != prev["p"] or p["e"] != prev["e"])
86	        if keep:
87	            out.append(p)
88	            prev = p
89	    return out
90	
91	
92	def main() -> None:
93	    src = sys.argv[1] if len(sys.argv) > 1 else "out/elbow_tube.gcode"
94	    dst = sys.argv[2] if len(sys.argv) > 2 else "out/elbow_tube_machine.html"
95	
96	    # Decimation volontairement TRES haute : mesure sur cette piece, passer
97	    # de 20077 a 6730 points triple le pas angulaire median (0.41 -> 1.23
98	    # deg) et fait passer le p95 de 2.4 a 7.1 deg. Un saut de plateau de 7
99	    # deg entre deux images se voit comme un a-coup. 20077 points quantifies
100	    # a 2 decimales pesent ~500 Ko : largement sous la limite de 16 Mo, donc
101	    # rien ne justifie de les jeter.
102	    pts = decimate(parse(src), 40000)
103	
104	    # quantification : 2 decimales suffisent a 0.01 mm / 0.01 deg, et divise
105	    # le poids du JSON par ~2 par rapport aux flottants bruts.
106	    data = [[round(p["r"], 2), round(p["c"], 2), round(p["z"], 2),
107	             round(p["b"], 2), 1 if p["e"] else 0,
108	             ["base", "pilier", "coude", "surplomb"].index(p["p"])]
109	            for p in pts]
110	
111	    stats = {
112	        "n": len(pts),
113	        "cmin": min(p["c"] for p in pts), "cmax": max(p["c"] for p in pts),
114	        "rmin": min(p["r"] for p in pts), "rmax": max(p["r"] for p in pts),
115	        "zmax": max(p["z"] for p in pts),
116	        "bmax": max(p["b"] for p in pts),
117	        "src": os.path.basename(src),
118	    }
119	
120	    html = TEMPLATE.replace("__DATA__", json.dumps(data, separators=(",", ":")))
121	    html = html.replace("__STATS__", json.dumps(stats, separators=(",", ":")))
122	
123	    if os.path.dirname(dst):
124	        os.makedirs(os.path.dirname(dst), exist_ok=True)
125	    with open(dst, "w", encoding="utf-8") as f:
126	        f.write(html)
127	
128	    print(f"lu    : {src}")
129	    print(f"ecrit : {dst}  ({os.path.getsize(dst)//1024} Ko)")
130	    print(f"points: {len(pts)}")
131	    print(f"C {stats['cmin']:.1f}..{stats['cmax']:.1f}  "
132	          f"R {stats['rmin']:.1f}..{stats['rmax']:.1f}  B max {stats['bmax']:.1f}")
133	
134	
135	TEMPLATE = r"""<title>Apex 4 Axes</title>
