function pointXYZ(p, cNow) {
  // p = [r, c, z, b, e, phase].
  //
  // La tete depose toujours dans le demi-plan machine y=0, a (r, 0, z) :
  // c'est le PLATEAU qui a tourne de c pour amener ce point sous elle. Vu
  // du repere machine a l'instant ou le plateau est a cNow, ce depot a donc
  // tourne de (cNow - c) depuis. D'ou une seule rotation, d'angle
  // (cNow - c), appliquee au point (r, 0).
  const a = (cNow - p[1]) * Math.PI / 180;
  const r = p[0];
  return [r * Math.cos(a), r * Math.sin(a), p[2]];
}

