import re,math,importlib.util
spec=importlib.util.spec_from_file_location("g","scripts/gen_elbow_tube_gcode.py")
m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
rx=re.compile(r"^G00 Y(-?\d+\.\d+) X(-?\d+\.\d+) Z(-?\d+\.\d+) B(-?\d+\.\d+)(?: E(-?\d+\.\d+))?")
pts=[]
for ln in open("out/elbow_tube_x1.gcode"):
    g=rx.match(ln.strip())
    if g and g.group(5): pts.append(tuple(map(float,g.groups()[:4])))
OFF=m.PART_OFFSET_R
def cross(a,b,c,d):
    o=lambda p,q,r:(q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0])
    return o(a,b,c)*o(a,b,d)<0 and o(c,d,a)*o(c,d,b)<0
for L in (0,20,40,60):
    layers={}
    for c,r,z,b in pts:
        B=math.radians(b); ra=r-L*math.sin(B); a=math.radians(c)
        k=round(m.height_field(r*math.cos(a)-OFF,z)/m.LAYER_HEIGHT)
        if k<2: continue
        layers.setdefault(k,[]).append((ra*math.cos(a),ra*math.sin(a),b,L*(1-math.cos(B))))
    first=None; n8=0
    for k in sorted(layers):
        q=[(p[0],p[1]) for p in layers[k][::2]]; n=len(q)
        hit=any(cross(q[i],q[i+1],q[j],q[j+1]) for i in range(n-1) for j in range(i+2,n-1) if not(i==0 and j==n-2))
        if hit:
            n8+=1
            if first is None: first=(k,layers[k][0][2],layers[k][0][3])
    if first: print(f"L={L:2d} mm : premier 8 a la couche {first[0]}, B={first[1]:.1f} deg, buse decollee de {first[2]:.1f} mm ; {n8} couches en 8 au total")
    else: print(f"L={L:2d} mm : aucun 8")
PY

